from collections import deque

def bfs(graph, s):
    dist = {s: 0}
    q = deque([s])
    while q:
        v = q.popleft()
        # INVARIANT: vertices leave the queue in nondecreasing dist order,
        # so the first time we set dist[w], it is the shortest path length.
        for w in graph.get(v, []):
            if w not in dist:
                dist[w] = dist[v] + 1
                q.append(w)
    return dist

g = {'a': ['b','c'], 'b': ['d'], 'c': ['d'], 'd': []}
print(bfs(g, 'a'))  # {'a':0,'b':1,'c':1,'d':2}
# Proof sketch: BFS explores in waves; wave k = distance k. First visit is shortest.

